use crate::domains::kernel_opt::corpus::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        KernelRule {
            rule_id: "kv-reuse-prefix-ends-at-last-evaluated-token".to_string(),
            gpu_concept: "A live/prefix KV-reuse checkpoint keyed on RENDERED conversation text must end exactly at the last token whose KV was actually EVALUATED -- and generation that stops at a mid-turn structural terminator (tool decoding halts at `</tool_call>`, BEFORE the assistant end token `<|im_end|>`) leaves the boundary token UN-EVALUATED, so its bytes must be trimmed out of the remembered text. Remembering the full rendered turn admits a token into the reuse prefix whose KV entry does not exist; the next request's prefix match silently consumes it and generation attends over a hole (wrong context, no error). The symmetric failure strands warm reuse: clearing the checkpoint at ANY tool-call finish forces clients that omit reasoning blocks to re-prefill the whole conversation on every tool turn. So the contract is three-armed: (1) remember prompt + sampled-suffix-minus-un-evaluated-terminator when the decode finished at the structural stop OUTSIDE any thinking span; (2) gate the remember on the DECODE finish reason, never the parser's promoted status -- repaired, truncated, recovered-from-unclosed-thinking, non-chat, imaged, and API-aliased paths do not reproduce what a re-render would produce, so their sampled text is not a valid reuse frontier (remember-or-clear: fall back to clearing, never to a stale bank); (3) a boundary regression test asserts the next render STARTS WITH the remembered visible text and its tail begins with the missing boundary token. Distinct from prefix-reuse-key-must-mirror-the-restore-predicate (B106 batch -- the KEY's policy-set must match the restore path's serving modes; this is the PREFIX CONTENT's token-level boundary vs evaluated KV), from request-arrival-work-asks-reuse-state-first (arrival-time work gating on the warm bank; this crafts the bank entry itself), and from write-before-read-state-skips-checkpoint (device-state backup sets; this is the text-side reuse frontier). Source: ivanfioravanti/ds4-metal @ ffd85d42 (MIT) -- commit 658b2fc 'Preserve Qwen tool-turn KV reuse and assistant boundaries' (ds4_server.c): the contract comment 'Tool decoding stops at </tool_call>, BEFORE the assistant end token. Leave <|im_end|> out of the visible key so the next suffix actually evaluates it.' (ds4_server.c:12194-12196 at the pin), the finish-reason gate 'Use the decode finish, not the parser's promoted tool_calls status: repaired/truncated output and unclosed reasoning are not this frontier.' (:12208-12209), the trim `buf_append(&visible, suffix, strlen(suffix) - strlen(\"<|im_end|>\"));` (:12214), and the remember-or-clear fallback (:13766-13772). Batch 125 / Plan 106 / Research 148.".to_string(),
            ref_shape: "// the visible key is the FULL rendered turn -- including the assistant\n// end token that tool decoding stopped BEFORE. The next request's prefix\n// match consumes a KV entry that was never written.\nfn remember_turn_checkpoint(rendered: &str) -> Checkpoint {\n    Checkpoint { visible: rendered.to_string() } // <|im_end|> has no KV\n}\n\n// the other failure: ANY tool-call finish clears the bank -- warm reuse\n// stranded for reasoning-omitting clients.\nfn on_tool_call_finish(slot: &mut Slot) {\n    thinking_live_clear(&mut slot.kv); // whole-conversation re-prefill next turn\n}\n".to_string(),
            opt_pattern: "// remember prompt + sampled suffix MINUS the un-evaluated terminator,\n// gated on the decode finish reason; anything suspect clears (never a\n// stale bank).\nfn remember_turn_checkpoint(prompt: &str, suffix: &str, finish: Finish) -> Option<Checkpoint> {\n    let usable = matches!(finish, Finish::ToolCallStop)\n        && !finish.repaired()\n        && !finish.inside_thinking();\n    if !usable {\n        return None; // caller clears: re-prefill beats a hole\n    }\n    let visible = suffix.strip_suffix(\"<|im_end|>\")?; // boundary has no KV yet\n    Some(Checkpoint { visible: format!(\"{prompt}{visible}\") })\n}\n\n#[test]\nfn boundary_is_evaluated_next_turn() {\n    let cp = remember_turn_checkpoint(\"p\", \"answer<|im_end|>\", Finish::ToolCallStop).unwrap();\n    let next = render_next_turn(&cp);\n    assert!(next.starts_with(&cp.visible)); // prefix match consumes only real KV\n    assert!(next[cp.visible.len()..].starts_with(\"<|im_end|>\")); // evaluated fresh\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "new-syntax-family-enumerates-every-keyed-surface".to_string(),
            gpu_concept: "An LLM-serving stack keys MANY independent surfaces by model syntax family -- raw-stream marker trackers, per-family prompt builders, per-family parsers, and per-binary CLI option parsers sharing one engine config. Adding a family to the renderer + core parser without extending EVERY keyed surface compiles clean and fails three different ways: the tracker's family dispatch fell through to the orphan-ending arm so valid tool calls were classified as orphans and the visible tool-turn KV checkpoint was never saved (SILENT perf loss -- the reuse feature just stops engaging, no error anywhere); the family's prompt builder ignored the vision capability flag so an image tool was never advertised (silent capability loss); and a CLI option parser never assigned the flag although help text advertised it (LOUD exit 2, but only at user time). The fix contract has three parts: (1) every family-keyed dispatch enumerates ALL families explicitly -- no silent default arm that swallows a supported family; (2) adding a family triggers an audit over every dispatch/builder/parser keyed on the family enum (the enum IS the checklist); (3) a POSITIVE per-family engagement regression test asserts the downstream feature actually FIRES (tracker reaches its terminal state, capability schema present iff the flag, option round-trips into the config field) -- a no-crash test proves nothing, the failure mode IS silent non-engagement. Distinct from shape-class-keyed-capability (B103 -- capability verdicts keyed by a shape tuple; this is surface-completeness across model families), from derived-key-single-constructor-parity-test (key-DERIVATION duplication; this is dispatch-MEMBERSHIP omission across consumers of one enum), and from implemented-surface-requires-provisioning-target (B122 -- a feature needs its fetch target; this is one feature fanned across N keyed surfaces all needing the member). Source: ivanfioravanti/ds4-metal @ ffd85d42 (MIT) -- commit ffd85d4 'Preserve Qwen tool handling and validate the main rebase' (+ 4010cc6 the config-surface rider): the family-keyed dispatch gaining the QWEN member (ds4_server.c:7246-7249 at the pin: `if (dt->model_syntax == SERVER_MODEL_SYNTAX_GLM || dt->model_syntax == SERVER_MODEL_SYNTAX_QWEN) { syn = dt->model_syntax == SERVER_MODEL_SYNTAX_QWEN ? &qwen_tool_syntax : &glm_tool_syntax;`), the per-family syntax table (`static const dsml_syntax qwen_tool_syntax = { \"<tool_call>\", \"</tool_call>\", \"<function=\", \"</function>\", \"<parameter=\", \"</parameter>\", };` :7034-7037), the vision flag now threaded through the family's builder (ds4_agent.c:1393: `if (syntax == AGENT_TOOL_SYNTAX_QWEN) return agent_build_qwen_tools_prompt(edit_upto, ds4_engine_has_vision(engine));`), and the rider: 4010cc6 wired `--ple` in the agent's option parser with a parse-round-trip test over the shared engine-config struct (ds4_agent.c:784-785 in the diff) -- three per-binary parsers, one missing member, loud at user time. Batch 125 / Plan 106 / Research 148.".to_string(),
            ref_shape: "// the family enum grew; the tracker's dispatch did not -- Qwen tool\n// calls fall through to the orphan arm and the KV checkpoint never saves.\nmatch syntax {\n    Syntax::Glm => syn = &glm_tool_syntax,\n    _ => end_as_orphan(), // silently swallows the supported family\n}\n\n// the builder ignores the capability flag for the new family:\nfn build_tools_prompt(syntax: Syntax) -> String {\n    match syntax {\n        Syntax::Qwen => build_qwen_tools_prompt(false), // vision never advertised\n        Syntax::Glm => build_glm_tools_prompt(engine.has_vision()),\n    }\n}\n".to_string(),
            opt_pattern: "// every family-keyed surface enumerates ALL families; the enum is the\n// audit checklist; a POSITIVE engagement test per family.\nfn syntax_table(syntax: Syntax) -> &'static SyntaxTable {\n    match syntax {\n        Syntax::Glm => &glm_tool_syntax,\n        Syntax::Qwen => &qwen_tool_syntax, // added WITH the family\n    }\n}\n\nfn build_tools_prompt(syntax: Syntax, engine: &Engine) -> String {\n    // capability flag threaded through EVERY family's builder\n    match syntax {\n        Syntax::Qwen => build_qwen_tools_prompt(engine.has_vision()),\n        Syntax::Glm => build_glm_tools_prompt(engine.has_vision()),\n    }\n}\n\n#[test]\nfn qwen_family_fires_every_surface() {\n    let t = track_stream(qwen_sample_with_tool_call());\n    assert_eq!(t.state, TrackState::Done); // the feature ENGAGES, not just no-crash\n    assert!(schema_offers_view_image());\n    let cfg = parse(&[\"--ple\", \"side.ple\"]);\n    assert_eq!(cfg.engine.ple_path.as_deref(), Some(\"side.ple\")); // round-trips\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "interleave-independent-accumulators-only".to_string(),
            gpu_concept: "In a parity-gated kernel (bit-identity, full-vector identity, exact-reference gates), a throughput restructure -- interleaving output rows per simdgroup, hoisting shared reductions out of a chunk loop, widening rows-per-group -- is legal ONLY across accumulator-INDEPENDENT sums: any reassociation of a consumer-visible sum's operand order is forbidden even when it buys bandwidth or dispatch count and passes argmax smoke tests. The legal form keeps the reference lane mapping, the per-block visit order, and the per-element adds VERBATIM, and interleaves/hoists only what the gate cannot observe: independent rows or projections, and reductions that are exactly invariant (same operands, same order, recomputed identically per consumer). The source names the tempting illegal merge in its own comment: 'combining the chunk dots would change rounding.' This is the ORDER axis at fixed precision -- precision-choice-per-consumer is a different rule (operand-precision-gated-by-consumer-invariance chooses the tolerance; this rule keeps the textual accumulation order so the exact gate never moves at all), reduction-restructure-needs-source-owned-comparator verifies a restructure that DID redistribute a sum via an explicit source-owned comparator (compose: that pin, or this refusal), and tree-reduction-depth-over-sequential-accumulate CHOOSES reassociation for accuracy on gradient paths -- the opposite trade under a different gate. Distinct from bit-exact-dispatch-fusion-boundary-emulation (fuses DEPENDENT dispatches under boundary-emulation machinery; this restructures WITHIN one kernel without touching any sum's order), and from dispatch-cliff-bitexact-shape-confinement (confines a width-wall family switch to shapes where drift is confined; this is the in-kernel restructure discipline that keeps every shape on the exact path). Twin instances, both from one commit: the Q4K gate/up multi-row dot (metal/qwen4.metal:1854-1857 at the pin: 'Q4_K gate/up input reuse with the original qwen4_row_dot lane mapping and accumulation order. Each lane still visits every block in order and adds its eight elements individually; only independent rows/projections are interleaved. NR output rows per SIMD group.') and the chunked norm+inject hoist (:132-135: 'Large batches have enough (token, stream) groups to compute the stream RMS once and reuse it for all eight chunks. Keep the 128-thread RMS reduction, each chunk's injection reduction, and the partial layout identical to the original kernel: combining the chunk dots would change rounding.'). Source: ivanfioravanti/ds4-metal @ ffd85d42 (MIT), commit f91e217 'Restore Qwen numerical parity and optimize Metal inference'. Batch 125 / Plan 106 / Research 148.".to_string(),
            ref_shape: "// throughput restructure that reassociates a consumer-visible sum:\n// the chunk dots are combined into one accumulator -- different rounding,\n// the exact-parity gate fails even though argmax smoke still passes.\nfn norm_inject_fused(x: &mut [f32], chunks: usize) {\n    let inv = rms_inv(x); // once, hoisted -- fine\n    let mut dot = 0.0f32;\n    for c in 0..chunks {\n        for (i, v) in chunk(x, c).iter().enumerate() {\n            dot += v * w(i); // ALL chunks share ONE running sum: reordered\n        }\n    }\n    apply(x, inv, dot);\n}\n".to_string(),
            opt_pattern: "// interleave independent rows; hoist exactly-invariant reductions;\n// every consumer-visible sum keeps its textual order.\nfn norm_inject_fused(x: &mut [f32], chunks: usize) {\n    let inv = rms_inv_128thread(x); // hoisted: SAME reduction tree as reference\n    for c in 0..chunks {\n        let dot = chunk_dot_reference_order(x, c); // per-chunk sum, order verbatim\n        apply_chunk(x, c, inv, dot);\n    }\n}\n\nfn gate_up_q4k_multirow(rows: &[Row], x: &q4k::Vec) -> [[f32; 2]; NR] {\n    let mut out = [[0.0f32; 2]; NR];\n    for (r, row) in rows.iter().enumerate() {\n        // each lane visits every block IN ORDER, adds its 8 elements\n        // individually -- only the ROWS are interleaved across simdgroups\n        out[r] = row.dot_reference_order(x);\n    }\n    out\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "fixed-point-parity-needs-reference-rounding".to_string(),
            gpu_concept: "A fixed-point reimplementation of a reference's linear transform (color conversion, dequant scale, activation table) must replicate the reference's COEFFICIENT PRECISION and ROUNDING MODE, not merely its formula: reduced-precision constants combined with truncating arithmetic shifts impose a systematic NEGATIVE half-LSB directional bias on every output channel -- small enough to pass smoke and argmax checks, large enough to fail exact-parity gates, and worst on saturated or edge content where the bias is visible as color shift / banding. The fix shape is exactly three moves and nothing else: widen the constants to the reference's precision (the JFIF-fixed-point convention: coefficients scaled 1<<16), add the round-half constant (+ (1 << (bits-1))) before every arithmetic right shift, and clamp after the rounding shift. DOMAIN CAVEAT (honest): this is the corpus's first CPU-side instance -- the family lives in image/codec parity, not GPU kernels; it lands here because the DECISION CONTENT is the exactness family's (reference-rounding replication under a parity gate), the same content the GPU exactness rules carry, and kernel-reimplementations of reference transforms (activation tables, dequant scales) hit the identical class. Distinct from operand-precision-gated-by-consumer-invariance (B118 -- CHOOSES precision per consumer tolerance between arms; this replicates one reference's arithmetic at fixed width so an exact gate holds), from exhaustive-domain-input-patch-bit-identity (Batch 115 -- patches the divergent INPUTS post-hoc after measuring the divergence; this fixes the ARITHMETIC CLASS at the source so no input diverges), and from bit-exact-dispatch-fusion-boundary-emulation (emulates dispatch boundaries in a fused chain; this is a single fixed-point transform's rounding contract). Companion parity shapes from the same commit (recorded, not ruled): chroma upsampling must match the reference's interpolation FILTER (box replication vs triangle at pixel centers) and clamp indices to the LOGICAL component extent, never the padded MCU storage extent (jpeg.h:653-654 at the pin). Source: ivanfioravanti/ds4-metal @ ffd85d42 (MIT) -- commit 681b9ce 'Fix JPEG decoding parity and separate vision quantization checks' (third_party/iris/jpeg.h): 'Round the full-precision color transform, avoiding a half-level bias from truncating each channel's contribution.' + `int r = yy + ((crr * 91881 + 32768) >> 16);` (jpeg.h:640-643 -- JFIF-precision <<16 coefficients, round-half constant, the old code used 8-bit-ish 359/88/183/454 with bare >>8); the gate is EXACT array equality vs Pillow/libjpeg over progressive x subsampling x odd-edge fixtures (tests/test_jpeg_decode.py: assert_array_equal). Batch 125 / Plan 106 / Research 148.".to_string(),
            ref_shape: "// truncated shifts + 8-bit-ish constants: a -0.5 LSB directional bias\n// per channel, invisible in smoke checks, fatal to exact-parity gates.\nfn ycbcr_to_rgb(y: i32, cb: i32, cr: i32) -> (i32, i32, i32) {\n    let r = y + ((359 * cr) >> 8); // truncated: biased low by up to 1 LSB\n    let g = y - ((88 * cb + 183 * cr) >> 8);\n    let b = y + ((454 * cb) >> 8);\n    (r, g, b)\n}\n".to_string(),
            opt_pattern: "// reference precision (<<16) + round-half before the shift + clamp.\nfn ycbcr_to_rgb(y: i32, cb: i32, cr: i32) -> (i32, i32, i32) {\n    let r = clamp(y + ((91881 * cr + 32768) >> 16)); // JFIF fixed-point\n    let g = clamp(y - ((22554 * cb + 46802 * cr + 32768) >> 16));\n    let b = clamp(y + ((116130 * cb + 32768) >> 16));\n    (r, g, b)\n}\n\nfn clamp(v: i32) -> i32 {\n    v.clamp(0, 255)\n}\n".to_string(),
        },
    ]
}
